/bin/bash -lc "python3 - <<'PY'
from solution.config_upgrade import ConfigurationError, _SubstitutionResolver

cases = [
    ({'a': '"'${b}'"', 'b': '"'${a}'"'}, ('a', 'b')),
    ({'a': '"'${b}'"', 'b': '"'${c}'"', 'c': '"'${a}'"'}, ('a', 'b', 'c')),
]
for config, expected in cases:
    try:
        _SubstitutionResolver(config).resolve_tree(config)
    except ConfigurationError as exc:
        message = str(exc)
        assert all(name in message for name in expected), message
        print(message)
    else:
        raise AssertionError('cycle accepted')

for config, expected in [({'a': '"'${missing}'"'}, 'missing'), ({'a': '"'${obj}'"', 'obj': {'x': 1}}, 'obj')]:
    try:
        _SubstitutionResolver(config).resolve_tree(config)
    except ConfigurationError as exc:
        assert expected in str(exc), exc
        print(exc)
    else:
        raise AssertionError('invalid reference accepted')
PY

